-- Rações de referência (ref_racoes.csv)
COMMIT;

-- Contadores IDENTITY depois dos IDs inseridos explicitamente
ALTER TABLE T_CLYVO_ESPECIE MODIFY (id_especie GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE T_CLYVO_DOENCA MODIFY (id_doenca GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE T_CLYVO_REF_PESO_RACA MODIFY (id_ref_peso GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE T_CLYVO_PREDISP_RACA MODIFY (id_predisp_raca GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE T_CLYVO_VACINA MODIFY (id_vacina GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE T_CLYVO_VACINA_DOENCA MODIFY (id_vacina_doenca GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE T_CLYVO_REF_CONSUMO MODIFY (id_ref_consumo GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE T_CLYVO_REF_RACAO MODIFY (id_ref_racao GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));

-- Conferência
SELECT 'T_CLYVO_ESPECIE' AS tabela, COUNT(*) AS qtd FROM T_CLYVO_ESPECIE
UNION ALL SELECT 'T_CLYVO_DOENCA' AS tabela, COUNT(*) AS qtd FROM T_CLYVO_DOENCA
UNION ALL SELECT 'T_CLYVO_REF_PESO_RACA' AS tabela, COUNT(*) AS qtd FROM T_CLYVO_REF_PESO_RACA
UNION ALL SELECT 'T_CLYVO_PREDISP_RACA' AS tabela, COUNT(*) AS qtd FROM T_CLYVO_PREDISP_RACA
UNION ALL SELECT 'T_CLYVO_VACINA' AS tabela, COUNT(*) AS qtd FROM T_CLYVO_VACINA
UNION ALL SELECT 'T_CLYVO_VACINA_DOENCA' AS tabela, COUNT(*) AS qtd FROM T_CLYVO_VACINA_DOENCA
UNION ALL SELECT 'T_CLYVO_REF_CONSUMO' AS tabela, COUNT(*) AS qtd FROM T_CLYVO_REF_CONSUMO
UNION ALL SELECT 'T_CLYVO_REF_RACAO' AS tabela, COUNT(*) AS qtd FROM T_CLYVO_REF_RACAO;
