INSERT INTO T_CLYVO_ESPECIE (id_especie, nm_especie) VALUES (1, 'Canina');
INSERT INTO T_CLYVO_ESPECIE (id_especie, nm_especie) VALUES (2, 'Felina');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (1, 'Cinomose', 'Canina', 'INFECCIOSA', 'S', 'N', 'S', 'N', NULL, NULL, NULL, 0, 0, 0, NULL, 'goticulas no ar de animais infectados; muito contagiosa', 'vacina essencial (V8/V10)', NULL, 'Uberaba-MG: 81% dos caes doentes sem vacina (45,6%) ou com vacina atrasada (35,6%) (Santos et al. 2013, Vet Noticias)', 'Merck/MSD Veterinary Manual - Canine Distemper; WSAVA (2024) Guidelines for the Vaccination of Dogs and Cats', 'https://www.merckvetmanual.com/infectious-diseases/canine-distemper/canine-distemper');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (2, 'Parvovirose', 'Canina', 'INFECCIOSA', 'S', 'N', 'S', 'N', NULL, NULL, NULL, 0, 0, 0, NULL, 'fezes e ambiente contaminado; virus resiste meses no ambiente', 'vacina essencial (V8/V10)', NULL, 'Niteroi-RJ: casos o ano todo, sem pico; 70% em filhotes de 2 a 4 meses, maioria sem vacina (Garcia et al. 2000, Braz J Vet Res Anim Sci)', 'Merck/MSD Veterinary Manual - Canine Parvovirus Infection; WSAVA (2024) Guidelines for the Vaccination of Dogs and Cats', 'https://www.merckvetmanual.com/digestive-system/infectious-diseases-of-the-gastrointestinal-tract-in-small-animals/canine-parvovirus-infection-parvoviral-enteritis-in-dogs');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (3, 'Tosse dos canis (gripe canina)', 'Canina', 'INFECCIOSA', 'S', 'N', 'S', 'N', NULL, NULL, NULL, 0, 0, 0, NULL, 'espalha rapido onde ha muitos caes juntos (creche, hotel, clinica)', 'vacina opcional (Bordetella + parainfluenza, ''vacina da gripe''); parainfluenza tambem na V8/V10', NULL, NULL, 'Merck/MSD Veterinary Manual - Kennel Cough; WSAVA (2024) Guidelines for the Vaccination of Dogs and Cats', 'https://www.merckvetmanual.com/respiratory-system/respiratory-diseases-of-small-animals/kennel-cough');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (4, 'Leptospirose', 'Canina', 'INFECCIOSA', 'S', 'S', 'S', 'N', 10, 3, NULL, 0, 0, 0, NULL, 'urina de animais infectados e agua contaminada', 'vacina essencial onde a doenca e comum, como no Brasil (V8/V10)', NULL, 'Minas Gerais, 2001-2017: maior ocorrencia no periodo chuvoso, de outubro a marco, com pico em janeiro (casos humanos; Silva et al. 2021, Res Soc Dev 10(1))', 'Merck/MSD Veterinary Manual - Leptospirosis in Dogs; WSAVA (2024) Guidelines for the Vaccination of Dogs and Cats; Silva et al. (2021)', 'https://rsdjournal.org/index.php/rsd/article/download/12089/10886');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (5, 'Erliquiose (doença do carrapato)', 'Canina', 'INFECCIOSA', 'N', 'N', 'S', 'N', NULL, NULL, NULL, 0, 0, 0, NULL, 'picada do carrapato marrom do cao (Rhipicephalus sanguineus)', 'nao ha vacina; controle de carrapatos', NULL, 'cerca de 20% dos caes atendidos em clinicas brasileiras tem anticorpos; endemica em areas urbanas com muito carrapato (Azevedo et al. 2011, Braz J Vet Res Anim Sci)', 'Merck/MSD Veterinary Manual - Ehrlichiosis; Azevedo et al. (2011)', 'https://merckvetmanual.com/infectious-diseases/rickettsial-diseases/ehrlichiosis-anaplasmosis-and-related-infections-in-animals');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (6, 'Panleucopenia felina', 'Felina', 'INFECCIOSA', 'S', 'N', 'S', 'N', NULL, NULL, NULL, 0, 0, 0, NULL, 'fezes, secrecoes e objetos contaminados; virus resiste ate 1 ano no ambiente', 'vacina essencial (V3/V4/V5 felina)', NULL, NULL, 'Merck/MSD Veterinary Manual - Feline Panleukopenia; WSAVA (2024) Guidelines for the Vaccination of Dogs and Cats', 'https://www.merckvetmanual.com/infectious-diseases/feline-panleukopenia/feline-panleukopenia');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (7, 'Rinotraqueite felina', 'Felina', 'INFECCIOSA', 'S', 'N', 'S', 'N', NULL, NULL, NULL, 0, 0, 0, NULL, 'goticulas e objetos; gatos recuperados podem transmitir por meses', 'vacina essencial (V3/V4/V5 felina)', NULL, NULL, 'Merck/MSD Veterinary Manual - Feline Respiratory Disease Complex; WSAVA (2024) Guidelines for the Vaccination of Dogs and Cats', 'https://www.merckvetmanual.com/respiratory-system/respiratory-diseases-of-small-animals/feline-respiratory-disease-complex');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (8, 'Esporotricose', 'Felina', 'INFECCIOSA', 'S', 'S', 'S', 'N', NULL, NULL, NULL, 0, 0, 0, NULL, 'arranhao, mordida ou contato com feridas de gatos infectados', 'nao ha vacina; higiene no manejo e gato sem acesso a rua', NULL, 'cidade de Sao Paulo: casos animais confirmados passaram de 2.417 (2022) para 3.309 (2023); 97% dos casos suspeitos de 2011 a 2022 eram gatos (CRMV-SP, Nota Tecnica 001/2025)', 'Merck/MSD Veterinary Manual - Sporotrichosis in Animals; CRMV-SP Nota Tecnica 001/2025', 'https://crmvsp.gov.br/wp-content/uploads/2025/08/NOTA-TECNICA-00001.2025-ESPOROTRICOSE-CRMV_SP-15.12.2025.pdf');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (9, 'Artrose', 'Canina', 'CRONICA', 'N', 'N', 'N', 'N', NULL, NULL, 6, 0, 0, -1, 'INICIAL', 'nao transmissivel', NULL, 'claudicacao, demora para levantar, menos saltos e brincadeiras', NULL, 'Idade: Anderson et al. (2018) Sci Rep 8:5641 | Sinal: Merck/MSD Veterinary Manual - Osteoarthritis in Dogs and Cats', 'https://www.merckvetmanual.com/musculoskeletal-system/osteoarthritis-in-dogs-and-cats/osteoarthritis-in-dogs-and-cats');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (10, 'Obesidade', 'Canina', 'CRONICA', 'N', 'N', 'N', 'N', NULL, NULL, 3, 1, 0, -1, 'INICIAL', 'nao transmissivel', NULL, 'peso acima da faixa ideal (correlacao 1) com consumo acima do esperado (correlacao 4)', NULL, 'Idade: Pegram et al. (2021) J Small Anim Pract | Sinal: Pegram et al. (2021) J Small Anim Pract', 'https://doi.org/10.1111/jsap.13325');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (11, 'Hipotireoidismo', 'Canina', 'CRONICA', 'N', 'N', 'N', 'N', NULL, NULL, 5.7, 0, 0, -1, 'INICIAL', 'nao transmissivel', NULL, 'ganho de peso, letargia, perda de pelo, intolerancia ao frio', NULL, 'Idade: O''Neill et al. (2022) Canine Med Genet 9:11 | Sinal: O''Neill et al. (2022) Canine Med Genet 9:11', 'https://doi.org/10.1186/s40575-022-00123-8');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (12, 'Doença degenerativa da válvula mitral', 'Canina', 'CRONICA', 'N', 'N', 'N', 'N', NULL, NULL, 8.4, 0, 0, -1, 'TARDIO', 'nao transmissivel', NULL, 'sem sinais nas fases inicial e intermediaria (apenas sopro); na insuficiencia cardiaca: respiracao rapida e dificil, tosse, desmaio', NULL, 'Idade: Mattin et al. (2015) J Vet Intern Med 29:847-854 | Sinal: Merck/MSD Veterinary Manual - Myxomatous Atrioventricular Valve Degeneration', 'https://www.merckvetmanual.com/circulatory-system/various-heart-diseases-in-dogs-and-cats/myxomatous-atrioventricular-valve-degeneration-in-dogs-and-cats');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (13, 'Síndrome de Cushing', 'Canina', 'CRONICA', 'N', 'N', 'N', 'N', NULL, NULL, 9, 1, 1, 0, 'INICIAL', 'nao transmissivel', NULL, 'aumento de sede e de urina, aumento de apetite, abdomen pendulo, ofegancia, perda de pelo', NULL, 'Idade: Schofield et al. (2022) J Small Anim Pract 63(4) | Sinal: Merck/MSD Veterinary Manual - Cushing Syndrome (Hyperadrenocorticism) in Animals', 'https://www.msdvetmanual.com/endocrine-system/the-adrenal-glands/cushing-syndrome-hyperadrenocorticism-in-animals');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (14, 'Hipoadrenocorticismo (Addison)', 'Canina', 'CRONICA', 'N', 'N', 'N', 'N', NULL, NULL, 3.2, -1, 0, -1, 'INICIAL', 'nao transmissivel', NULL, 'letargia (77%), falta de apetite (73%), vomito (73%), fraqueza (38%), perda de peso (29%)', NULL, 'Idade: Schofield et al. (2021) J Small Anim Pract 62:343-350 | Sinal: Schofield et al. (2021) J Small Anim Pract 62:343-350', 'https://doi.org/10.1111/jsap.13285');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (15, 'Diabetes mellitus', 'Felina', 'CRONICA', 'N', 'N', 'N', 'N', NULL, NULL, 8.3, 1, 1, 0, 'INICIAL', 'nao transmissivel', NULL, 'aumento de sede e de urina, aumento de apetite, perda de peso', NULL, 'Idade: Waite et al. (2025) J Vet Intern Med 39(4) | Sinal: Merck/MSD Veterinary Manual - Diabetes Mellitus in Dogs and Cats', 'https://www.merckvetmanual.com/endocrine-system/the-pancreas/diabetes-mellitus-in-dogs-and-cats');
INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (16, 'Doença renal policística', 'Felina', 'CRONICA', 'N', 'N', 'N', 'N', NULL, NULL, 3, 0, 1, 0, 'INICIAL', 'nao transmissivel', NULL, 'cistos podem nao dar sinais ou levar a doenca renal cronica; na doenca renal, aumento de sede e de urina sao os primeiros sinais', NULL, 'Idade: Barrs et al. (2001), citado por Arruda et al. (2015) Semina: Ciencias Agrarias 36(1):301-306 (UNESP) | Sinal: Merck/MSD Veterinary Manual - Renal Anomalies in Animals; Renal Dysfunction in Dogs and Cats', 'https://www.merckvetmanual.com/urinary-system/noninfectious-diseases-of-the-urinary-system-in-small-animals/renal-dysfunction-in-dogs-and-cats');
