INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (18, 'Raiva', 'Canina', 'INFECCIOSA', 'S', 'S', 'N', 'S', NULL, NULL, NULL, 0, 0, 0, NULL, 'saliva de animal infectado, geralmente por mordida; em SP, todos os casos desde 1998 vieram de morcegos', 'vacina antirrabica anual', NULL, 'estado de SP, 2002 a ago/2023: 15 caes e 22 gatos confirmados, todos por variantes de morcego; notificacao obrigatoria de caso suspeito', 'Instituto Pasteur / SES-SP (2025) Informe Tecnico 01; Prefeitura de Guarulhos Nota Informativa 05/2023; Merck/MSD Veterinary Manual - Rabies in Animals', 'https://www.guarulhos.sp.gov.br/sites/default/files/file/arquivos/Nota%20Informativa%202023%20n%C2%B0%2005%20Raiva.pdf');
