INSERT INTO T_CLYVO_DOENCA (id_doenca, nm_doenca, especie_alvo, tp_doenca, contagiosa, zoonose, monitora_surto, alerta_caso_unico, mes_inicio_pico, mes_fim_pico, idade_risco_anos, sinal_comida, sinal_agua, sinal_movimento, momento_sinal, ds_transmissao, ds_prevencao, ds_sinais_clinicos, ds_dados_brasil, ds_fonte, ds_link) VALUES (20, 'Hepatite infecciosa canina', 'Canina', 'INFECCIOSA', 'S', 'N', 'N', 'N', NULL, NULL, NULL, 0, 0, 0, NULL, 'contato com urina, fezes e saliva de caes infectados', 'vacina essencial (adenovirus, na V8/V10)', NULL, 'incomum onde ha vacinacao de rotina, mas ainda causa surtos periodicos (Manual MSD)', 'Merck/MSD Veterinary Manual - Infectious Canine Hepatitis; Day et al. (2016) WSAVA Guidelines (adenovirus canino como vacina essencial)', 'https://www.merckvetmanual.com/infectious-diseases/infectious-canine-hepatitis/infectious-canine-hepatitis');
